def predict(board, action):
    if isinstance(action, tuple):
        row, col = action
    else:
        row, col = action[0], action[1]

    if row < 0 or row >= 64 or col < 0 or col >= 64:
        return board

    old_char = board[row][col]
    if old_char == 'g':
        new_char = 'N'
    elif old_char == 'W':
        new_char = 'G'
    else:
        return board

    board[row][col] = new_char

    if new_char == 'N':
        for dr in [-1, 0, 1]:
            for dc in [-1, 0, 1]:
                if dr == 0 and dc == 0:
                    continue
                new_row, new_col = row + dr, col + dc
                if 0 <= new_row < 64 and 0 <= new_col < 64 and board[new_row][new_col] == 'g':
                    board[new_row][new_col] = 'N'
    elif new_char == 'G':
        board[row][col] = 'W'

    return ["".join(row) for row in board]
